package com.mohymods.kingdomsmp.economy;
import static org.junit.jupiter.api.Assertions.*;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import java.util.*;
import java.nio.file.Path;
import java.io.IOException;
import net.minecraft.nbt.CompoundTag;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
/** Pure canonical boundary model, separate from the real native enchanting/inspection fixture. */
class LibraryNativeOutputStoreTest {
 @TempDir Path directory;
 @Test void libraryOutputsRespectApprovedInspectionsPurposeAndAtomicOnceOnlyXpRecovery()throws Exception{
  var p=UUID.randomUUID();var s=EconomyStore.open(directory);s.changeProfession(UUID.randomUUID(),p,"enroll","","librarian");var sample=item(0);assertThrows(IllegalStateException.class,()->s.issueNativeOutput(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_ENCHANT,sample));assertThrows(IllegalStateException.class,()->s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,"kingdom_smp:librarian/a03","Premature setup model must refuse"));s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,"kingdom_smp:librarian/a02","Pure canonical approved readable area model");assertThrows(IllegalStateException.class,()->s.issueNativeOutput(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_ENCHANT,sample));s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,"kingdom_smp:librarian/a03","Pure canonical inspected native setup model");
  Map<UUID,CompoundTag> items=new HashMap<>();for(int n=0;n<4;n++){var id=UUID.randomUUID();var item=item(n);s.issueNativeOutput(id,p,NativeOutputQuests.LIBRARY_ENCHANT,item);items.put(id,item);assertFalse(s.matchesEnchantedOutput(id,p,item));assertFalse(s.matchesNativeOutput(id,UUID.randomUUID(),NativeOutputQuests.LIBRARY_ENCHANT,item));}var first=s.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_ENCHANT,items,4);assertFalse(s.recoverItem(new EconomyStore.Receipt(s.id(),s.expectedReceipt(p))));assertEquals(200,s.professions(p).track(Profession.LIBRARIAN).xp());var q=s.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_ENCHANT,items,4);var faulty=EconomyStore.open(directory,(file,data)->{AtomicNbt.write(file,data);throw new IOException("Library native receipt after rename");});assertThrows(IOException.class,()->faulty.recoverItem(new EconomyStore.Receipt(s.id(),q.sequence())));var restored=EconomyStore.open(directory);assertFalse(restored.recoverItem(new EconomyStore.Receipt(s.id(),q.sequence())));assertEquals(300,restored.professions(p).track(Profession.LIBRARIAN).xp());items.forEach((id,item)->assertFalse(restored.matchesNativeOutput(id,p,NativeOutputQuests.LIBRARY_ENCHANT,item)));assertThrows(IllegalStateException.class,()->restored.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_ENCHANT,items,4));assertEquals(0,restored.balance(p));assertTrue(restored.mailbox(p).isEmpty());restored.archive(p,"Purpose-bound library output model audit");assertEquals(300,EconomyStore.open(directory).professions(p).track(Profession.LIBRARIAN).xp());
 }
 @Test void compatibleBookCommissionsHaveTheirOwnPurposeAndCannotSkipCataloguePrerequisites()throws Exception{
  var p=UUID.randomUUID();var s=EconomyStore.open(directory);s.changeProfession(UUID.randomUUID(),p,"enroll","","librarian");Map<UUID,CompoundTag> items=new HashMap<>();for(int n=0;n<4;n++){var id=UUID.randomUUID();var item=item(n);item.putString("id","minecraft:enchanted_book");s.issueNativeOutput(id,p,NativeOutputQuests.LIBRARY_BOOKS,item);items.put(id,item);assertFalse(s.matchesNativeOutput(id,p,NativeOutputQuests.LIBRARY_ENCHANT,item));}var q=s.prepareNativeOutputDelivery(UUID.randomUUID(),p,NativeOutputQuests.LIBRARY_BOOKS,items,4);s.recoverItem(new EconomyStore.Receipt(s.id(),q.sequence()));assertEquals(100,s.professions(p).track(Profession.LIBRARIAN).xp());assertThrows(IllegalStateException.class,()->s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,"kingdom_smp:librarian/a06","Missing actual enchanting objective"));assertThrows(IllegalStateException.class,()->s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),p,"kingdom_smp:librarian/a08","Missing full earlier band"));items.forEach((id,item)->assertFalse(s.matchesNativeOutput(id,p,NativeOutputQuests.LIBRARY_BOOKS,item)));assertEquals(s.professions(p),EconomyStore.open(directory).professions(p));
 }
 static CompoundTag item(int n){var item=new CompoundTag();item.putString("id","minecraft:iron_pickaxe");item.putInt("count",1);var components=new CompoundTag();components.putInt("minecraft:repair_cost",n);item.put("components",components);return item;}
}
